contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= value, "not enough balance");
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        c.withdraw(value); if (__ESBMC_reverted()) return;
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert(
            beforeBalanceC - afterBalanceC == value &&
            afterDeposits == beforeDeposits &&
            afterBalanceThis >= beforeBalanceThis
        );
    }

    receive() external payable {}
}

