pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(c).balance >= value);
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        try c.withdraw(value) {} catch { return; }
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        assertTrue(beforeBalanceC - afterBalanceC == value &&
            afterDeposits == beforeDeposits &&
            afterBalanceThis >= beforeBalanceThis);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
